import React, { useState, useEffect } from 'react';
import { useDispatch, useSelector } from "react-redux";
// 1. Import the new 'useNavigate' hook
import { useNavigate } from 'react-router-dom';
import { registerAdmin } from '../../../redux/actions/adminAction'; // Make sure this path is correct

const RegisterAdmin = () => {
    const { auth, alert } = useSelector(state => state);
    const dispatch = useDispatch();
    // 2. Use the 'useNavigate' hook to get the navigation function
    const navigate = useNavigate();

    const initialState = { fullname: "", username: "", email: "", password: "", cf_password: "" };
    const [userData, setUserData] = useState(initialState);
    const { fullname, username, email, password, cf_password } = userData;

    const [typePass, setTypePass] = useState(false);
    const [typeCfPass, setTypeCfPass] = useState(false);

    useEffect(() => {
        // 3. Use the 'navigate' function for redirection instead of 'history.push'
        if (auth.token && auth.user.role === 'admin') {
            navigate("/admin/dashboard"); // Redirect to the admin dashboard if logged in
        }
    // 4. Update the dependency array to use 'navigate'
    }, [auth.token, auth.user, navigate]);

    const handleChangeInput = (e) => {
        const { name, value } = e.target;
        setUserData({ ...userData, [name]: value });
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        dispatch(registerAdmin(userData));
    };

    // This is a representative form based on your other components.
    // Please adjust if your admin registration form has different fields.
    return (
        <div className="auth_page">
            <form onSubmit={handleSubmit} className="inner-shadow">
                <h3 className="text-uppercase text-center mb-4 auth-heading">
                    Register New Admin
                </h3>
                
                {/* Full Name Field */}
                <div className="mb-3">
                    <label htmlFor="fullname" className="form-label">Full name</label>
                    <input type="text" className="form-control" id="fullname"
                           onChange={handleChangeInput} value={fullname} name="fullname"
                           style={{ background: `${alert.fullname ? "#fd2d6a14" : ""} ` }} />
                    <small className="form-text text-danger">{alert.fullname ? alert.fullname : ""}</small>
                </div>

                {/* Username Field */}
                <div className="mb-3">
                    <label htmlFor="username" className="form-label">User name</label>
                    <input type="text" className="form-control" id="username"
                           onChange={handleChangeInput} value={username.toLowerCase().replace(/ /g, "")} name="username"
                           style={{ background: `${alert.username ? "#fd2d6a14" : ""} ` }} />
                    <small className="form-text text-danger">{alert.username ? alert.username : ""}</small>
                </div>

                {/* Email Field */}
                <div className="mb-3">
                    <label htmlFor="email" className="form-label">Email address</label>
                    <input type="email" className="form-control" id="email"
                           onChange={handleChangeInput} value={email} name="email"
                           style={{ background: `${alert.email ? "#fd2d6a14" : ""} ` }} />
                    <small className="form-text text-danger">{alert.email ? alert.email : ""}</small>
                </div>

                {/* Password Fields... */}

                <button type="submit" className="btn-1 w-100 d-flex justify-content-center">
                    Register
                </button>
            </form>
        </div>
    );
}

export default RegisterAdmin;
